    /// a person's File ▸ Open or Finder double-click on its concurrent read
    /// queue (`canConcurrentlyReadDocuments`), so the main thread is free
    /// for the built-in copy's progress window, which `watch` feeds and
    /// whose Cancel stops the copy (spec §11 #228-P; `probeForOpening`
    /// passes it there). An agent's `open_project` reads on the lane's
    /// thread inside `withoutAsking` (spec §11 #231), where no watch is
    /// passed: main is free, and the call waits the copy's length with no
    /// window. A read AppKit itself runs ON main passes no watch either, and
    /// there a copy — or an ffmpeg conversion, on any door, which reports no
    /// progress — blocks the window for its length; ffmpeg's consent alert
    /// states the cost first.
    private static func probeAllowingRewrap(
        _ url: URL, mayAsk: Bool, watch: RewrapWatch?
    ) throws -> MediaDescriptor {
        do {
            return withCursorBeside(try waitForProbe(url), movie: url)  // spec §11 CU-34 (a)
        } catch let failure as ImportError where failure.invitesFFmpeg && !isImage(url) {
            // Images are excluded because ImageIO's refusal means the picture
            // is corrupt, not that the container is exotic — and a PNG is not
            // something to hand to a video converter.
            guard ContainerRewrap.isMatroska(url) else {
                return try probeConverted(url, failure: failure, mayAsk: mayAsk)
            }
            // A WebM or Matroska file is copied into a movie with no question
            // (spec §11 #216-R). Only a codec the copy cannot carry goes on
            // to the opt-in ffmpeg step; every other refusal is final.
            do {
                return try probeCopy(try ContainerRewrap.assist(url, watch: watch), of: url)
            } catch let refusal as ContainerRewrapError where refusal.invitesFFmpeg {
                return try probeConverted(url, failure: refusal, mayAsk: mayAsk)
            }
        }
    }

    /// The opt-in ffmpeg step, and its result probed, with `url` recorded as
    /// its `original` (spec §11 #233); `failure` is what is thrown when there
    /// is no conversion or it will not open. `mayAsk` is the caller's (spec
    /// §11 MC-5): a tool call's is false, so it never raises the consent
    /// question.
    ///
    /// There is ONE second attempt (spec §11 #227): when ffmpeg failed, a
    /// VP9 copy failed its frame check, or the file will not open, the step
    /// is asked again to re-encode a VP9 stream it had copied, with the
    /// first attempt's plan. A source whose plan copied no VP9 gets no
    /// second call, and then the first attempt's error is the one thrown. A
    /// timeout is not tried again.
    private static func probeConverted(
        _ url: URL, failure: any Error, mayAsk: Bool
    ) throws -> MediaDescriptor {
        var remembered = failure
        var converted: URL?
        var failed = false
        var planned: FFmpegRewrap.Plan?
        do {
            converted = try FFmpegRewrap.assist(url, mayAsk: mayAsk, planned: &planned)
        } catch let refusal as FFmpegRewrap.RewrapError {
            guard case .failed = refusal else { throw refusal }
            (remembered, failed) = (refusal, true)
        }
        if let converted {
            if let descriptor = probeConversion(converted, of: url) { return descriptor }
        } else if !failed {
            throw failure
        }
        if let planned, !planned.copiesVP9 { throw remembered }
        guard
            let again = try FFmpegRewrap.assist(
                url, mayAsk: mayAsk, planned: &planned, reencodingVP9: true)
        else { throw remembered }
        guard let descriptor = probeConversion(again, of: url) else { throw failure }
        return descriptor
    }

    /// A conversion of `url` probed, with `url` as its `original`; nil, and
    /// the file thrown away, when AVFoundation still will not open it. The
    /// conversion is cached by name, so leaving it there would hand the same
    /// broken result back for ever; throwing it away makes the next attempt
    /// a real attempt. Only the file that was probed is thrown away: one
    /// another import has since put at the name is left (spec §11 #227). The
    /// error its caller reports is the ORIGINAL one, because the file the
    /// user chose is the one they are being told about.
    private static func probeConversion(_ rewrapped: URL, of url: URL) -> MediaDescriptor? {
        let probed = FFmpegRewrap.fileNumber(of: rewrapped)
        guard var descriptor = try? waitForProbe(rewrapped) else {
            FFmpegRewrap.discard(rewrapped, ifStill: probed)
            return nil
        }
        descriptor.original = MediaOriginal(of: url)
        return descriptor
    }

