import AVFoundation
import Foundation
import ImageIO
import UniformTypeIdentifiers

// The same list and the same test as MediaImporter+Probe.swift:70-80.
let imageTypes: [UTType] = [.png, .jpeg, .heic, .heif, .tiff, .gif, .bmp, .webP]
func isImage(_ url: URL) -> Bool {
    guard let type = UTType(filenameExtension: url.pathExtension.lowercased()) else { return false }
    return imageTypes.contains { type.conforms(to: $0) }
}

let path = CommandLine.arguments[1]
let url = URL(fileURLWithPath: path)
let type = UTType(filenameExtension: "avif")
print("UTType:", type?.identifier ?? "nil", "image?", type?.conforms(to: .image) ?? false)
print("supertypes:", type?.supertypes.map(\.identifier).sorted() ?? [])
print("audiovisual?", type?.conforms(to: .audiovisualContent) ?? false, "movie?", type?.conforms(to: .movie) ?? false)
print("isImage:", isImage(url))

if let source = CGImageSourceCreateWithURL(url as CFURL, nil) {
    print("ImageIO type:", CGImageSourceGetType(source) as String? ?? "nil", "count:", CGImageSourceGetCount(source))
    let props = CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [CFString: Any]
    print("ImageIO size:", props?[kCGImagePropertyPixelWidth] ?? "nil", props?[kCGImagePropertyPixelHeight] ?? "nil")
    print("decoded:", CGImageSourceCreateImageAtIndex(source, 0, nil) != nil)
} else {
    print("ImageIO: no source")
}
let readable = CGImageSourceCopyTypeIdentifiers() as? [String] ?? []
print("ImageIO reads public.avif:", readable.contains("public.avif"))

let semaphore = DispatchSemaphore(value: 0)
Task.detached {
    let asset = AVURLAsset(url: url)
    do {
        let tracks = try await asset.load(.tracks)
        let duration = try await asset.load(.duration)
        print("AVURLAsset tracks:", tracks.count, "duration:", duration.seconds)
    } catch {
        let e = error as NSError
        print("AVURLAsset refused:", e.domain, e.code, e.localizedDescription)
    }
    semaphore.signal()
}
semaphore.wait()

